/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

// Read all input
const input = readFileSync(0, 'utf8')

// Parse mode
const argv = process.argv.slice(2)
if (argv.length !== 1 || !['merge', 'merge2', 'regions'].includes(argv[0])) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}
const mode = argv[0]

// Parse documents
let lines = input.split('\n')
// Drop empty tail if present
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

const parts = []
let current = []
for (const line of lines) {
  if (line === '%%%') {
    parts.push(current)
    current = []
  } else {
    current.push(line)
  }
}
parts.push(current)

if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

const [mine, base, theirs] = parts

/**
 * Compute greedy LCS between doc and base.
 * Returns list of [baseIdx, docIdx] pairs for matching lines.
 */
function computeLCS(doc, base) {
  const matches = []
  let baseIdx = 0, docIdx = 0

  while (baseIdx < base.length && docIdx < doc.length) {
    if (base[baseIdx] === doc[docIdx]) {
      matches.push([baseIdx, docIdx])
      baseIdx++
      docIdx++
    } else {
      const baseRemaining = base.length - baseIdx
      const docRemaining = doc.length - docIdx

      // Advance the side with more remaining lines (prefer base on tie)
      if (docRemaining > baseRemaining) {
        docIdx++
      } else {
        baseIdx++
      }
    }
  }

  return matches
}

/**
 * Extract changes from LCS.
 * Each change is a run of base lines replaced by a run of doc lines.
 */
function getChanges(doc, base, matches) {
  const changes = []

  let prevBaseIdx = -1
  let prevDocIdx = -1

  for (const [baseIdx, docIdx] of matches) {
    if (prevBaseIdx + 1 < baseIdx || prevDocIdx + 1 < docIdx) {
      changes.push({
        baseStart: prevBaseIdx + 1,
        baseEnd: baseIdx,
        lines: doc.slice(prevDocIdx + 1, docIdx)
      })
    }
    prevBaseIdx = baseIdx
    prevDocIdx = docIdx
  }

  // Handle remaining lines after last match
  if (prevBaseIdx + 1 < base.length || prevDocIdx + 1 < doc.length) {
    changes.push({
      baseStart: prevBaseIdx + 1,
      baseEnd: base.length,
      lines: doc.slice(prevDocIdx + 1)
    })
  }

  return changes
}

/**
 * Get what a side produces for a region by applying its changes to the base.
 */
function getSideVersionOfRegion(changes, base, regionStart, regionEnd) {
  const relevantChanges = changes
    .filter(c => c.baseStart < regionEnd && c.baseEnd > regionStart)
    .sort((a, b) => a.baseStart - b.baseStart)

  if (relevantChanges.length === 0) {
    return base.slice(regionStart, regionEnd)
  }

  const result = []
  let currentIdx = regionStart

  for (const change of relevantChanges) {
    // Add unchanged base lines before this change
    if (currentIdx < change.baseStart) {
      result.push(...base.slice(currentIdx, change.baseStart))
    }
    // Add the change's lines
    result.push(...change.lines)
    // Update current position
    currentIdx = change.baseEnd
  }

  // Add remaining base lines after the last change
  if (currentIdx < regionEnd) {
    result.push(...base.slice(currentIdx, regionEnd))
  }

  return result
}

/**
 * Compare two line arrays for equality.
 */
function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

// Compute LCS for both sides
const mineLCS = computeLCS(mine, base)
const theirLCS = computeLCS(theirs, base)

// Get changes
const mineChanges = getChanges(mine, base, mineLCS)
const theirChanges = getChanges(theirs, base, theirLCS)

// Merge changes - gather them in order of base start, mine before theirs for ties
const allChanges = []
for (const change of mineChanges) {
  allChanges.push({ ...change, side: 'mine' })
}
for (const change of theirChanges) {
  allChanges.push({ ...change, side: 'theirs' })
}

allChanges.sort((a, b) => {
  if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
  return a.side === 'mine' ? -1 : 1
})

// Create regions
const regions = []
let baseIdx = 0
let changeIdx = 0

while (changeIdx < allChanges.length) {
  const firstChange = allChanges[changeIdx]

  // Add stable region before this change if any
  if (baseIdx < firstChange.baseStart) {
    regions.push({
      type: 'stable',
      baseStart: baseIdx,
      baseEnd: firstChange.baseStart,
      lines: base.slice(baseIdx, firstChange.baseStart)
    })
  }

  // Create region starting at first change
  let regionBaseEnd = firstChange.baseEnd
  const mineChangesInRegion = []
  const theirChangesInRegion = []

  if (firstChange.side === 'mine') {
    mineChangesInRegion.push(firstChange)
  } else {
    theirChangesInRegion.push(firstChange)
  }

  changeIdx++

  // Absorb overlapping changes
  while (changeIdx < allChanges.length && allChanges[changeIdx].baseStart <= regionBaseEnd) {
    const change = allChanges[changeIdx]
    regionBaseEnd = Math.max(regionBaseEnd, change.baseEnd)

    if (change.side === 'mine') {
      mineChangesInRegion.push(change)
    } else {
      theirChangesInRegion.push(change)
    }

    changeIdx++
  }

  // Create conflict region
  regions.push({
    type: 'conflict',
    baseStart: firstChange.baseStart,
    baseEnd: regionBaseEnd,
    mineChanges: mineChangesInRegion,
    theirChanges: theirChangesInRegion
  })

  baseIdx = regionBaseEnd
}

// Add final stable region if any
if (baseIdx < base.length) {
  regions.push({
    type: 'stable',
    baseStart: baseIdx,
    baseEnd: base.length,
    lines: base.slice(baseIdx)
  })
}

// Resolve regions
function resolveRegion(region) {
  if (region.type === 'stable') {
    return {
      type: 'stable',
      lines: region.lines
    }
  }

  const { baseStart, baseEnd, mineChanges, theirChanges } = region
  const baseLines = base.slice(baseStart, baseEnd)

  if (mineChanges.length === 0) {
    // Only theirs changed
    const theirLines = getSideVersionOfRegion(theirChanges, base, baseStart, baseEnd)
    return { type: 'theirs', lines: theirLines }
  }

  if (theirChanges.length === 0) {
    // Only mine changed
    const mineLines = getSideVersionOfRegion(mineChanges, base, baseStart, baseEnd)
    return { type: 'mine', lines: mineLines }
  }

  // Both sides changed - compute what each produces
  const mineLines = getSideVersionOfRegion(mineChanges, base, baseStart, baseEnd)
  const theirLines = getSideVersionOfRegion(theirChanges, base, baseStart, baseEnd)

  // Compare
  if (linesEqual(mineLines, theirLines)) {
    return { type: 'both', lines: mineLines }
  }

  if (linesEqual(mineLines, baseLines)) {
    return { type: 'theirs', lines: theirLines }
  }

  if (linesEqual(theirLines, baseLines)) {
    return { type: 'mine', lines: mineLines }
  }

  return {
    type: 'conflict',
    mineLines,
    baseLines,
    theirLines
  }
}

// Resolve all regions
const resolvedRegions = regions.map(resolveRegion)

// Output
let hasConflict = false
const output = []

