  for (const region of resolvedRegions) {
    if (region.type === 'stable' || region.type === 'mine' || region.type === 'theirs' || region.type === 'both') {
      output.push(...region.lines)
    } else {
      hasConflict = true
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      if (mode === 'merge') {
        output.push('||||||| base')
        output.push(...region.baseLines)
      }
      output.push('=======')
      output.push(...region.theirLines)
      output.push('>>>>>>> theirs')
    }
  }

  const result = output.map(line => `${line}\n`).join('')
  process.stdout.write(result)
} else if (mode === 'regions') {
  for (const region of resolvedRegions) {
    if (region.type === 'stable') {
      output.push(`stable ${region.lines.length}`)
    } else if (region.type === 'mine') {
      output.push(`mine ${region.lines.length}`)
    } else if (region.type === 'theirs') {
      output.push(`theirs ${region.lines.length}`)
    } else if (region.type === 'both') {
      output.push(`both ${region.lines.length}`)
    } else {
      output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirLines.length}`)
      hasConflict = true
    }
  }

  process.stdout.write(output.map(line => `${line}\n`).join(''))
}

process.exit(hasConflict ? 1 : 0)
