/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

// Read all input
const input = readFileSync(0, 'utf8')

// Parse mode
const argv = process.argv.slice(2)
if (argv.length !== 1 || !['merge', 'merge2', 'regions'].includes(argv[0])) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}
const mode = argv[0]

...
} else if (mode === 'regions') {
  for (const region of resolvedRegions) {
    if (region.type === 'stable') {
      output.push(`stable ${region.lines.length}`)
    } else if (region.type === 'mine') {
      output.push(`mine ${region.lines.length}`)
    } else if (region.type === 'theirs') {
      output.push(`theirs ${region.lines.length}`)
    } else if (region.type === 'both') {
      output.push(`both ${region.lines.length}`)
    } else {
      output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirLines.length}`)
      hasConflict = true
    }
  }

