import { readFileSync } from 'fs'

// Read all input
const input = readFileSync(0, 'utf8')

// Parse mode
const argv = process.argv.slice(2)
if (argv.length !== 1 || !['merge', 'merge2', 'regions'].includes(argv[0])) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}
const mode = argv[0]

// Parse documents
let lines = input.split('\n')
// Drop empty tail if present
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

const parts = []
let current = []
for (const line of lines) {
  if (line === '%%%') {
    parts.push(current)
    current = []
  } else {
    current.push(line)
  }
}
parts.push(current)

if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

const [mine, base, theirs] = parts

/**
 * Compute greedy LCS between doc and base.
 * Returns list of [baseIdx, docIdx] pairs for matching lines.
 */
function computeLCS(doc, base) {
  const matches = []
  let baseIdx = 0, docIdx = 0

  while (baseIdx < base.length && docIdx < doc.length) {
    if (base[baseIdx] === doc[docIdx]) {
      matches.push([baseIdx, docIdx])
      baseIdx++
      docIdx++
    } else {
      const baseRemaining = base.length - baseIdx
      const docRemaining = doc.length - docIdx

      // Advance the side with more remaining lines (prefer base on tie)
      if (docRemaining > baseRemaining) {
        docIdx++
      } else {
        baseIdx++
      }
    }
  }

  return matches
}

/**
 * Extract changes from LCS.
 * Each change is a run of base lines replaced by a run of doc lines.
 */
function getChanges(doc, base, matches) {
  const changes = []

  let prevBaseIdx = -1
  let prevDocIdx = -1

  for (const [baseIdx, docIdx] of matches) {
    if (prevBaseIdx + 1 < baseIdx || prevDocIdx + 1 < docIdx) {
      changes.push({
        baseStart: prevBaseIdx + 1,
        baseEnd: baseIdx,
        lines: doc.slice(prevDocIdx + 1, docIdx)
      })
    }
    prevBaseIdx = baseIdx
    prevDocIdx = docIdx
  }

  // Handle remaining lines after last match
  if (prevBaseIdx + 1 < base.length || prevDocIdx + 1 < doc.length) {
    changes.push({
      baseStart: prevBaseIdx + 1,
      baseEnd: base.length,
      lines: doc.slice(prevDocIdx + 1)
    })
  }

